const email = $json;
const from = email.from?.value?.[0]?.address;
const to = email.to?.value?.[0]?.address;
if (!email.id || !email.threadId || !from || !to || !email.subject || !email.text || !email.date || !email.sizeEstimate) throw new Error('Gmail message lacks required intake fields');
if (from.toLowerCase() === to.toLowerCase()) throw new Error('Self-addressed message excluded');
if (email.sizeEstimate > 131072 || email.text.length > 16000) throw new Error('Gmail message exceeds intake limit');
return { json: { version: 1, messageId: email.id, threadId: email.threadId, from, to, subject: email.subject, text: email.text, messageDate: email.date, sizeEstimate: email.sizeEstimate } };
